	// New Code: Uses the Utilities Script Include called NeedItUtils.

	var niutils = new NeedItUtils();

	// Uncomment the below lines while using old conditional logic
	// var isPast = niutils.isDatePast(current.getValue('u_when_needed'));
	// var isToday = niutils.isDateToday(current.getValue('u_when_needed'));

	// if (isToday == true) { // Old. This can also be used
	if (niutils.isDateToday(current.getValue('u_when_needed'))) {
		gs.addErrorMessage("When needed date cannot be on the same day. The delivery of the service requires a minimum amount of time to fulfill. Your request has not been saved to the database.");
		current.setAbortAction(true);
	} 

	// else if (isPast == true) { // Old. This can also be used
	else if (niutils.isDatePast(current.getValue('u_when_needed'))) {
		gs.addErrorMessage("When needed date cannot be in the past.  Your request has not been saved to the database.");
		current.setAbortAction(true);
	} 

	else {
		gs.addInfoMessage("Your request has been succeessfully saved to the database. Please, spare some time to fulfill your request.");
	}

})(current, previous);
